"""Calculate calibrated solar production for the UTC day 2024-03-15."""

from datetime import datetime
from io import StringIO
import json
from pathlib import Path
import re

import pandas as pd


DATASET = Path('/app/dataset')
DAY_START = pd.Timestamp('2024-03-15', tz='UTC')
DAY_END = pd.Timestamp('2024-03-16', tz='UTC')

# Only completed work in maintenance_notes.txt invalidates readings. The
# cancelled Sakura inspection on March 15 does not create an exclusion.
COMPLETED_MAINTENANCE = {
    'FARM_C': [('2024-03-16 08:00:00', '2024-03-16 12:00:00')],
    'FARM_F': [('2024-03-15 12:00:00', '2024-03-15 14:00:00')],
}


def read_export(path: Path) -> pd.DataFrame:
    data = path.read_bytes()
    encoding = 'utf-16' if data.startswith((b'\xff\xfe', b'\xfe\xff')) else 'utf-8-sig'
    lines = data.decode(encoding).splitlines()
    header_index = next(
        i for i, line in enumerate(lines)
        if line.startswith('timestamp') and 'inverter_temperature_C' in line
    )
    separator = ';' if ';' in lines[header_index] else ','
    # Preserve column whitespace: several exports contain a distinct, misleading
    # column whose name differs from the calibrated column only by a space.
    return pd.read_csv(
        StringIO('\n'.join(lines[header_index:])),
        sep=separator,
        dtype=str,
    ).drop_duplicates()


def parse_timestamp(value):
    if not isinstance(value, str):
        return pd.NaT
    value = value.strip()
    for pattern, fmt in (
        (r'\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}', '%Y-%m-%d %H:%M:%S'),
        (r'\d{2}\.\d{2}\.\d{4} \d{2}:\d{2}:\d{2}', '%d.%m.%Y %H:%M:%S'),
    ):
        if re.fullmatch(pattern, value):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                return pd.NaT
    return pd.NaT


def parse_numbers(values: pd.Series) -> pd.Series:
    def normalize(value):
        if not isinstance(value, str):
            return value
        value = value.strip()
        # European numbers use '.' for grouping and ',' for the decimal mark.
        # Some error/sentinel and other numeric values still use decimal dots.
        if ',' in value:
            value = value.replace('.', '').replace(',', '.')
        return value

    return pd.to_numeric(values.map(normalize), errors='coerce')


def answer() -> dict[str, int]:
    farms = pd.read_csv(DATASET / 'farms.csv')
    registry = pd.read_csv(DATASET / 'farm_registry.csv')
    for frame in (farms, registry):
        frame['name_key'] = frame['farm_name'].str.strip().str.casefold()
    fleet = farms.merge(registry[['name_key', 'farm_id']], on='name_key', validate='one_to_one')

    calibration = json.loads((DATASET / 'sensors_calibration.json').read_text())
    calibration = calibration['enterprise_platform']['deployment_environments']['system_config']['farms']

    energy_to_kwh = {'kwh': 1.0, 'wh': 0.001, 'mwh': 1000.0, 'btu': 0.00029307107}
    power_to_kw = {'kw': 1.0, 'w': 0.001, 'mw': 1000.0}
    totals = {}

    for farm in fleet.itertuples(index=False):
        farm_id = farm.farm_id
        totals[farm_id] = 0
        path = DATASET / f'production_{farm_id}.csv'
        if not path.exists():
            continue
        settings = calibration[farm_id]
        sensor = settings['sensor_info']
        correction = settings['calibration_data']
        readings = read_export(path)
        timestamp_column = next(column for column in readings.columns if column.strip() == 'timestamp')
        local_times = pd.to_datetime(readings[timestamp_column].map(parse_timestamp))
        times = local_times.dt.tz_localize(
            farm.timezone, ambiguous='NaT', nonexistent='NaT'
        ).dt.tz_convert('UTC')

        # Infer the regular sampling interval from the complete timestamp stream,
        # before invalid values, maintenance, or the reporting-day filter remove
        # observations. Missing readings do not extend neighboring observations.
        intervals = times.dropna().drop_duplicates().sort_values().diff().dropna()
        interval_hours = intervals.median().total_seconds() / 3600 if not intervals.empty else 0.0

        recorded = parse_numbers(readings[correction['value_column_name']])
        true_values = recorded - float(correction['calibration_offset'])
        valid = times.notna() & true_values.notna() & true_values.ge(0)

        temperatures = parse_numbers(readings['inverter_temperature_C'])
        for spike in times[temperatures.gt(85.0) & times.notna()]:
            valid &= ~((times >= spike) & (times < spike + pd.Timedelta(minutes=45)))

        for local_start, local_end in COMPLETED_MAINTENANCE.get(farm_id, []):
            start = pd.Timestamp(local_start).tz_localize(farm.timezone).tz_convert('UTC')
            end = pd.Timestamp(local_end).tz_localize(farm.timezone).tz_convert('UTC')
            valid &= ~((times >= start) & (times < end))

        valid &= (times >= DAY_START) & (times < DAY_END)
        unit = sensor['unit'].strip().lower()
        if sensor['reading_type'].strip().lower() == 'energy':
            total_kwh = true_values[valid].sum() * energy_to_kwh[unit]
        else:
            total_kwh = true_values[valid].sum() * power_to_kw[unit] * interval_hours
        totals[farm_id] = round(float(total_kwh))

    return totals


